export default function Page() {
  const [clients, setClients] = useState(initialClients)
  const [query, setQuery] = useState('')
  const [selected, setSelected] = useState<Client | null>(null)
  const [showNew, setShowNew] = useState(false)
  const [view, setView] = useState<'clientes' | 'ventas' | 'reactivacion' | 'productos' | 'finanzas' | 'reportes'>('clientes')
  const filtered = useMemo(() => clients.filter(client => `${client.first} ${client.last} ${client.phone}`.toLowerCase().includes(query.toLowerCase())), [clients, query])
  const active = clients.filter(client => client.status === 'Activo').length
  const toReactivate = clients.length - active

  if (selected) return <ClientDetail client={selected} onBack={() => setSelected(null)} />
  if (view === 'ventas') return <Sales onNavigate={setView} />
  if (view === 'reactivacion') return <Reactivation clients={clients} onNavigate={setView} />
  if (view === 'productos') return <Products onNavigate={setView} />
  if (view === 'finanzas') return <Finance onNavigate={setView} />
  if (view === 'reportes') return <Reports onNavigate={setView} />

  return <main className="app-shell"><Sidebar active="Clientes" onNavigate={setView} /><section className="main-content"><header className="topbar"><div className="breadcrumbs"><span>Glauss Shop</span><span>/</span><strong>Clientes</strong></div><div className="top-actions"><button className="icon-button" aria-label="Buscar"><Search /></button><button className="icon-button" aria-label="Notificaciones">●</button><button className="quick-button" onClick={() => setShowNew(true)}><Plus /> Nuevo cliente</button></div></header><div className="content-wrap clients-page"><div className="page-heading clients-heading"><div><p className="eyebrow">RELACIÓN CON CLIENTES</p><h1>Clientes</h1><p className="heading-subtitle">Conocé y gestioná a las personas que eligen tu tienda.</p></div><button className="quick-button" onClick={() => setShowNew(true)}><Plus /> Nuevo cliente</button></div><div className="clients-toolbar"><label className="search-control"><Search /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Buscar por nombre o teléfono..." /></label><span className="result-count">{filtered.length} clientes</span></div><div className="metrics-grid clients-metrics"><Metric icon={<Users />} label="Total de clientes" value={clients.length.toString()} tone="purple" /><Metric icon={<span className="metric-dot green" />} label="Clientes activos" value={active.toString()} tone="mint" /><Metric icon={<span className="metric-dot orange" />} label="Clientes a reactivar" value={toReactivate.toString()} tone="peach" /></div><div className="card clients-table-card"><div className="clients-table-head"><div><h2>Base de clientes</h2><p>Seguimiento de compras y actividad reciente</p></div><button className="date-button">Todos los estados <ChevronDown /></button></div><div className="sales-table-wrap"><table className="clients-table"><thead><tr><th>Nombre</th><th>Apellido</th><th>Teléfono</th><th>Última compra</th><th>Cantidad de compras</th><th>Total gastado ($)</th><th>Estado</th><th /></tr></thead><tbody>{filtered.map(client => <tr key={client.id} onClick={() => setSelected(client)}><td><div className="client-table"><span>{initials(client)}</span><strong>{client.first}</strong></div></td><td>{client.last}</td><td>{client.phone}</td><td>{client.lastPurchase}</td><td className="numeric-cell">{client.purchases}</td><td className="numeric-cell strong-cell">{money(client.spent)}</td><td><span className={`status-pill ${client.status === 'Activo' ? 'active-status' : 'reactivate-status'}`}>{client.status}</span></td><td><button className="row-more" aria-label={`Más opciones para ${client.first}`} onClick={event => event.stopPropagation()}><MoreHorizontal /></button></td></tr>)}</tbody></table></div><div className="clients-footer"><span>Mostrando {filtered.length} de {clients.length} clientes</span><div><button className="pagination-button" disabled><ChevronLeft /></button><button className="pagination-current">1</button><button className="pagination-button" disabled><ChevronRight /></button></div></div></div></div></section>{showNew && <NewClient onClose={() => setShowNew(false)} onCreate={client => { setClients([...clients, { ...client, id: clients.length + 1 }]); setShowNew(false) }} />}</main>
}

function Metric({ icon, label, value, tone }: { icon: React.ReactNode; label: string; value: string; tone: string }) { return <div className="metric-card"><div className={`metric-icon ${tone}`}>{icon}</div><span className="metric-title">{label}</span><div className="metric-value">{value}</div></div> }

function Sidebar({ active, onNavigate }: { active: string; onNavigate?: (view: 'clientes' | 'ventas' | 'reactivacion' | 'productos' | 'finanzas' | 'reportes') => void }) { return <aside className="sidebar"><div className="brand"><span className="brand-mark">g</span><span>glauss</span><span className="brand-dot">.</span></div><div className="workspace"><div className="workspace-avatar">GS</div><div><strong>Glauss Shop</strong><span>Mi tienda</span></div><ChevronDown /></div><nav className="nav-list"><span className="nav-label">MENU PRINCIPAL</span>{[['Resumen', '◈'], ['Ventas', '▣'], ['Clientes', '♙'], ['Reactivación', '↻'], ['Productos y stock', '□'], ['Finanzas', '$'], ['Reportes', '▤']].map(([label, icon]) => <button key={label} onClick={() => label === 'Clientes' ? onNavigate?.('clientes') : label === 'Ventas' ? onNavigate?.('ventas') : label === 'Reactivación' ? onNavigate?.('reactivacion') : label === 'Productos y stock' ? onNavigate?.('productos') : label === 'Finanzas' ? onNavigate?.('finanzas') : label === 'Reportes' ? onNavigate?.('reportes') : undefined} className={`nav-item ${label === active ? 'active' : ''}`}><span className="nav-glyph">{icon}</span>{label}{label === 'Clientes' && <span className="nav-count">12</span>}</button>)}</nav><div className="sidebar-bottom"><div className="upgrade-card"><div className="upgrade-icon">✦</div><strong>Desbloqueá todo el potencial</strong><p>Tené reportes avanzados y mucho más.</p><button>Conocer plan Pro →</button></div><button className="nav-item">? <span>Central de ayuda</span></button><button className="nav-item">⚙ <span>Configuración</span></button><div className="profile"><div className="profile-avatar">JS</div><div><strong>João Silva</strong><span>Administrador</span></div><MoreHorizontal /></div></div></aside> }

function Products({ onNavigate }: { onNavigate: (view: 'clientes' | 'reactivacion' | 'productos') => void }) {
  const [query, setQuery] = useState('')
  const [category, setCategory] = useState('Todas las categorías')
  const [menu, setMenu] = useState<number | null>(null)
  const [showProductModal, setShowProductModal] = useState(false)
  const categories = ['Descartables', 'Pods', 'Líquidos', 'Resistencias', 'Baterías y Mods', 'Accesorios']
  const rows = initialProducts.filter(product => `${product.name} ${product.brand}`.toLowerCase().includes(query.toLowerCase()) && (category === 'Todas las categorías' || product.category === category))
  const lowStock = initialProducts.filter(product => product.stock <= product.minimum).length
  return showProductModal ? <NewProduct onClose={() => setShowProductModal(false)} /> : <main className="app-shell"><Sidebar active="Productos y stock" onNavigate={onNavigate} /><section className="main-content"><header className="topbar"><div className="breadcrumbs"><span>Glauss Shop</span><span>/</span><strong>Productos y Stock</strong></div><div className="top-actions"><button className="icon-button" aria-label="Buscar"><Search /></button><button className="icon-button" aria-label="Notificaciones">●</button><button className="quick-button" onClick={() => setShowProductModal(true)}><Plus /> Nuevo producto</button></div></header><div className="content-wrap products-page"><div className="page-heading products-heading"><div><p className="eyebrow">CATÁLOGO E INVENTARIO</p><h1>Productos y Stock</h1><p className="heading-subtitle">Controlá tu catálogo y mantené siempre disponible lo que más vendés.</p></div><button className="quick-button" onClick={() => setShowProductModal(true)}><Plus /> Nuevo producto</button></div><div className="products-toolbar"><label className="search-control"><Search /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Buscar producto o marca..." /></label><label className="filter-control"><select value={category} onChange={event => setCategory(event.target.value)}><option>Todas las categorías</option>{categories.map(item => <option key={item}>{item}</option>)}</select><ChevronDown /></label><span className="result-count">{rows.length} productos</span></div><div className="metrics-grid products-metrics"><Metric icon={<ShoppingBag />} label="Total de productos" value={initialProducts.length.toString()} tone="purple" /><Metric icon={<span className="metric-dot orange" />} label="Productos con stock bajo" value={lowStock.toString()} tone="peach" /><Metric icon={<span className="metric-dot green" />} label="Marca más vendida" value="Elfbar" tone="mint" /></div><div className="card clients-table-card products-table-card"><div className="clients-table-head"><div><h2>Inventario</h2><p>Precios y disponibilidad de tu catálogo actual</p></div><span className="stock-legend"><i /> Stock bajo</span></div><div className="sales-table-wrap"><table className="clients-table products-table"><thead><tr><th>Producto</th><th>Marca</th><th>Categoría</th><th>Precio</th><th>Stock actual</th><th>Stock mínimo</th><th>Unidades vendidas</th><th></th></tr></thead><tbody>{rows.map(product => { const isLow = product.stock <= product.minimum; return <tr key={product.id} className={isLow ? 'low-stock-row' : ''}><td><strong>{product.name}</strong>{isLow && <span className="low-stock-pill">Stock bajo</span>}</td><td>{product.brand}</td><td><span className="category-pill">{product.category}</span></td><td className="strong-cell">{money(product.price)}</td><td className={isLow ? 'stock-number low' : 'stock-number'}>{product.stock}</td><td>{product.minimum}</td><td className="numeric-cell">{product.sold}</td><td className="action-cell"><button className="row-more" aria-label={`Acciones para ${product.name}`} onClick={() => setMenu(menu === product.id ? null : product.id)}><MoreHorizontal /></button>{menu === product.id && <div className="product-menu"><button>Editar</button><button>Eliminar</button></div>}</td></tr>})}</tbody></table></div></div></div></section></main>
}

