function Sales({ onNavigate }: { onNavigate: (view: 'clientes' | 'ventas' | 'reactivacion' | 'productos' | 'finanzas' | 'reportes') => void }) {
  const [query, setQuery] = useState('')
  const [method, setMethod] = useState('Todos')
  const [menu, setMenu] = useState<number | null>(null)
  const [page, setPage] = useState(1)
  const [showNewSale, setShowNewSale] = useState(false)
  const [selectedSale, setSelectedSale] = useState<Sale | null>(null)
  const rows = initialSales.filter(sale => sale.client.toLowerCase().includes(query.toLowerCase()) && (method === 'Todos' || sale.method === method))
  if (showNewSale) return <NewSaleModal onClose={() => setShowNewSale(false)} />
  if (selectedSale) return <SaleDetail sale={selectedSale} onBack={() => setSelectedSale(null)} />
  return <main className="app-shell"><Sidebar active="Ventas" onNavigate={onNavigate} /><section className="main-content"><header className="topbar"><div className="breadcrumbs"><span>Glauss Shop</span><span>/</span><strong>Ventas</strong></div><div className="top-actions"><button className="icon-button" aria-label="Buscar"><Search /></button><button className="icon-button" aria-label="Notificaciones">●</button></div></header><div className="content-wrap sales-page"><div className="page-heading sales-heading"><div><p className="eyebrow">HISTORIAL COMERCIAL</p><h1>Ventas</h1><p className="heading-subtitle">Consultá y gestioná todas las ventas de tu tienda.</p></div><button className="quick-button" onClick={() => setShowNewSale(true)}><Plus /> Nueva venta</button></div><div className="sales-filters"><label className="filter-control"><span>Desde</span><input type="date" defaultValue="2024-03-01" /></label><label className="filter-control"><span>Hasta</span><input type="date" defaultValue="2024-06-20" /></label><label className="filter-control"><select value={method} onChange={event => { setMethod(event.target.value); setPage(1) }}><option>Todos</option><option>Efectivo</option><option>Transferencia</option><option>Tarjeta</option></select><ChevronDown /></label><label className="search-control"><Search /><input value={query} onChange={event => { setQuery(event.target.value); setPage(1) }} placeholder="Buscar por cliente..." /></label></div><div className="card clients-table-card sales-table-card"><div className="sales-table-top"><div><h2>Historial de ventas</h2><p>{rows.length} operaciones registradas</p></div><span className="table-total">Total: {money(rows.reduce((sum, sale) => sum + sale.total, 0))}</span></div><div className="sales-table-wrap"><table className="clients-table sales-table"><thead><tr><th>N°</th><th>Fecha</th><th>Cliente</th><th>Productos</th><th>Método de pago</th><th>Total</th><th></th></tr></thead><tbody>{rows.map(sale => <tr key={sale.id} onClick={() => setSelectedSale(sale)}><td><strong>#{sale.id}</strong></td><td>{sale.date}</td><td><strong>{sale.client}</strong></td><td>{sale.products}</td><td><span className={`payment-pill ${sale.method.toLowerCase()}`}>{sale.method}</span></td><td><strong>{money(sale.total)}</strong></td><td className="actions-cell"><button className="more-button" aria-label={`Acciones venta ${sale.id}`} onClick={() => setMenu(menu === sale.id ? null : sale.id)}><MoreHorizontal /></button>{menu === sale.id && <div className="row-menu"><button>Ver detalle</button><button>Eliminar</button></div>}</td></tr>)}</tbody></table></div><div className="table-footer"><span>Mostrando {rows.length} de 15 ventas</span><div className="pagination"><button aria-label="Página anterior" onClick={() => setPage(Math.max(1, page - 1))}><ChevronLeft /></button><button className="current-page">{page}</button><button aria-label="Página siguiente" onClick={() => setPage(Math.min(2, page + 1))}><ChevronRight /></button></div></div></div></div></section></main>
}

function NewSaleModal({ onClose }: { onClose: () => void }) {
  const [clientQuery, setClientQuery] = useState('')
  const [selectedClient, setSelectedClient] = useState<Client | null>(null)
  const [productQuery, setProductQuery] = useState('')
  const [items, setItems] = useState<{ product: Product; quantity: number }[]>([])
  const [method, setMethod] = useState('Efectivo')
  const [date, setDate] = useState('2024-06-20')
  const matchingClients = initialClients.filter(client => `${client.first} ${client.last} ${client.phone}`.toLowerCase().includes(clientQuery.toLowerCase()))
  const matchingProducts = initialProducts.filter(product => `${product.name} ${product.brand}`.toLowerCase().includes(productQuery.toLowerCase())).slice(0, 5)
  const total = items.reduce((sum, item) => sum + item.product.price * item.quantity, 0)
  const addProduct = (product: Product) => { setItems(current => current.some(item => item.product.id === product.id) ? current : [...current, { product, quantity: 1 }]); setProductQuery('') }
  const updateQuantity = (id: number, amount: number) => setItems(current => current.map(item => item.product.id === id ? { ...item, quantity: Math.max(1, item.quantity + amount) } : item))
  return <div className="modal-backdrop"><section className="sale-modal new-client-modal new-sale-modal" role="dialog" aria-modal="true" aria-labelledby="new-sale-title"><header><div><p className="eyebrow">REGISTRAR OPERACIÓN</p><h2 id="new-sale-title">Nueva venta</h2></div><button className="close-button" onClick={onClose} aria-label="Cerrar"><X /></button></header><div className="modal-body sale-form-body"><label className="field"><span>Cliente</span><input value={selectedClient ? `${selectedClient.first} ${selectedClient.last}` : clientQuery} onChange={event => { setSelectedClient(null); setClientQuery(event.target.value) }} placeholder="Buscar cliente por nombre o teléfono..." />{!selectedClient && clientQuery && <div className="autocomplete-list">{matchingClients.slice(0, 4).map(client => <button type="button" key={client.id} onClick={() => { setSelectedClient(client); setClientQuery('') }}>{client.first} {client.last}<small>{client.phone}</small></button>)}<button type="button" className="create-client-option" onClick={() => setClientQuery('')}>+ Crear cliente nuevo</button></div>}</label><label className="field"><span>Productos</span><input value={productQuery} onChange={event => setProductQuery(event.target.value)} placeholder="Buscar producto para agregar..." />{productQuery && <div className="autocomplete-list">{matchingProducts.map(product => <button type="button" key={product.id} onClick={() => addProduct(product)}>{product.name}<small>{product.brand} · {money(product.price)}</small></button>)}</div>}</label><div className="sale-items">{items.length === 0 ? <p className="empty-items">Todavía no agregaste productos.</p> : items.map(item => <div className="sale-item" key={item.product.id}><div><strong>{item.product.name}</strong><small>{money(item.product.price)} c/u</small></div><div className="quantity-control"><button type="button" onClick={() => updateQuantity(item.product.id, -1)} aria-label={`Quitar una unidad de ${item.product.name}`}>−</button><b>{item.quantity}</b><button type="button" onClick={() => updateQuantity(item.product.id, 1)} aria-label={`Agregar una unidad de ${item.product.name}`}>+</button></div><strong>{money(item.product.price * item.quantity)}</strong></div>)}</div><div className="modal-fields"><label className="field"><span>Método de pago</span><select value={method} onChange={event => setMethod(event.target.value)}><option>Efectivo</option><option>Transferencia</option><option>Tarjeta</option></select></label><label className="field"><span>Fecha</span><input type="date" value={date} onChange={event => setDate(event.target.value)} /></label></div><div className="sale-total"><span>Total</span><strong>{money(total)}</strong></div></div><footer><button className="cancel-button" onClick={onClose}>Cancelar</button><button className="quick-button" disabled={!selectedClient || items.length === 0} onClick={onClose}>Registrar venta</button></footer></section></div>
}

function Finance({ onNavigate }: { onNavigate: (view: 'clientes' | 'ventas' | 'reactivacion' | 'productos' | 'finanzas' | 'reportes') => void }) {
  const [filter, setFilter] = useState('Todos')
  const [showExpense, setShowExpense] = useState(false)
  const movements = [
    { date: '20/06/2024', type: 'Ingreso', category: 'Venta', description: 'Venta N° 048', amount: 48200 },
    { date: '18/06/2024', type: 'Egreso', category: 'Alquiler', description: 'Alquiler del local', amount: 185000 },
    { date: '16/06/2024', type: 'Ingreso', category: 'Venta', description: 'Venta N° 047', amount: 36700 },
    { date: '14/06/2024', type: 'Egreso', category: 'Proveedores', description: 'Reposición de stock', amount: 92500 },
    { date: '11/06/2024', type: 'Ingreso', category: 'Venta', description: 'Venta N° 046', amount: 52900 },
    { date: '06/06/2024', type: 'Egreso', category: 'Servicios', description: 'Internet y servicios', amount: 24800 },
    { date: '03/06/2024', type: 'Ingreso', category: 'Venta', description: 'Venta N° 045', amount: 41800 },
    { date: '29/05/2024', type: 'Egreso', category: 'Proveedores', description: 'Compra mayorista', amount: 116000 },
  ]
  const visible = filter === 'Todos' ? movements : movements.filter(item => item.type === filter)
  const income = movements.filter(item => item.type === 'Ingreso').reduce((sum, item) => sum + item.amount, 0)
  const expense = movements.filter(item => item.type === 'Egreso').reduce((sum, item) => sum + item.amount, 0)
  const chart = [{ month: 'Ene', income: 210, expense: 130 }, { month: 'Feb', income: 265, expense: 170 }, { month: 'Mar', income: 320, expense: 205 }, { month: 'Abr', income: 290, expense: 245 }, { month: 'May', income: 380, expense: 225 }, { month: 'Jun', income: 180, expense: 145 }]
  return <main className="app-shell"><Sidebar active="Finanzas" onNavigate={onNavigate} /><section className="main-content"><header className="topbar"><div className="breadcrumbs"><span>Glauss Shop</span><span>/</span><strong>Finanzas</strong></div><div className="top-actions"><button className="icon-button" aria-label="Buscar"><Search /></button><button className="icon-button" aria-label="Notificaciones">●</button><button className="quick-button" onClick={() => setShowExpense(true)}><Plus /> Registrar egreso</button></div></header><div className="content-wrap finance-page"><div className="page-heading"><div><p className="eyebrow">CONTROL FINANCIERO</p><h1>Finanzas</h1><p className="heading-subtitle">Seguí tus ingresos, egresos y balance mes a mes.</p></div></div><div className="metrics-grid finance-metrics"><Metric icon={<span className="metric-dot green" />} label="Ingresos totales" value={money(income)} tone="mint" /><Metric icon={<span className="metric-dot red" />} label="Egresos totales" value={money(expense)} tone="peach" /><Metric icon={<span className="metric-dot purple" />} label="Balance" value={money(income - expense)} tone="purple" /></div><div className="card finance-chart-card"><div className="card-head"><div><h2>Ingresos vs Egresos</h2><p>Últimos 6 meses · en miles de pesos</p></div><div className="finance-legend"><span><i className="legend-income" />Ingresos</span><span><i className="legend-expense" />Egresos</span></div></div><div className="finance-chart">{chart.map(item => <div className="chart-month" key={item.month}><div className="bars"><span className="bar income-bar" style={{height: `${item.income / 4}px`}} /><span className="bar expense-bar" style={{height: `${item.expense / 4}px`}} /></div><small>{item.month}</small></div>)}</div></div><div className="finance-toolbar"><div className="filter-pills" role="group" aria-label="Filtrar movimientos">{['Todos', 'Ingresos', 'Egresos'].map(item => <button key={item} className={filter === item ? 'filter-pill selected' : 'filter-pill'} onClick={() => setFilter(item)}>{item}</button>)}</div><div className="finance-actions"><button className="date-button">01/01/2024 — 30/06/2024 <ChevronDown /></button><button className="quick-button" onClick={() => setShowExpense(true)}><Plus /> Registrar egreso</button></div></div><div className="card clients-table-card finance-table-card"><div className="clients-table-head"><div><h2>Movimientos</h2><p>Los ingresos se generan automáticamente desde tus ventas.</p></div><span className="result-count">{visible.length} movimientos</span></div><div className="sales-table-wrap"><table className="clients-table finance-table"><thead><tr><th>Fecha</th><th>Tipo</th><th>Categoría</th><th>Descripción</th><th>Monto ($)</th></tr></thead><tbody>{visible.map((item, index) => <tr key={`${item.date}-${index}`}><td>{item.date}</td><td><span className={`finance-type ${item.type === 'Ingreso' ? 'income' : 'expense'}`}>{item.type}</span></td><td>{item.category}</td><td className="strong-cell">{item.description}</td><td className={`finance-amount ${item.type === 'Ingreso' ? 'income-text' : 'expense-text'}`}>{item.type === 'Ingreso' ? '+' : '-'} {money(item.amount)}</td></tr>)}</tbody></table></div></div></div></section>{showExpense && <ExpenseModal onClose={() => setShowExpense(false)} />}</main>
}

function ExpenseModal({ onClose }: { onClose: () => void }) { return <div className="modal-backdrop"><section className="sale-modal new-client-modal" role="dialog" aria-modal="true" aria-labelledby="expense-title"><header><div><p className="eyebrow">CONTROL FINANCIERO</p><h2 id="expense-title">Registrar egreso</h2></div><button className="close-button" onClick={onClose} aria-label="Cerrar"><X /></button></header><div className="modal-body"><label className="field"><span>Fecha</span><input type="date" defaultValue="2024-06-20" /></label><label className="field"><span>Categoría</span><select defaultValue="Compra de mercadería"><option>Compra de mercadería</option><option>Alquiler</option><option>Sueldos</option><option>Servicios</option><option>Marketing</option><option>Otros</option></select></label><label className="field"><span>Descripción</span><input placeholder="Ej. Compra mayorista" /></label><label className="field"><span>Monto ($)</span><input type="number" min="0" placeholder="Ej. 25000" /></label></div><footer><button className="cancel-button" onClick={onClose}>Cancelar</button><button className="quick-button" onClick={onClose}>Registrar egreso</button></footer></section></div> }

function Reports({ onNavigate }: { onNavigate: (view: 'clientes' | 'reactivacion' | 'productos' | 'finanzas' | 'reportes') => void }) {
  const [range, setRange] = useState('Últimos 6 meses')
  const months = range === 'Este año' ? ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul'] : ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun']
  const products = [{ name: 'BC5000 Blue Razz', value: 48 }, { name: 'BC5000 Strawberry Kiwi', value: 42 }, { name: 'MO5000 Watermelon', value: 37 }, { name: 'OS5000 Blueberry', value: 31 }, { name: 'XROS 3 Mini', value: 26 }, { name: 'XROS Mesh 0.8Ω', value: 24 }, { name: 'Mango Ice 30ml', value: 22 }, { name: 'Líquido Menta 60ml', value: 20 }]
  const brands = [{ name: 'Elfbar', value: 103 }, { name: 'Lost Mary', value: 74 }, { name: 'Vaporesso', value: 68 }, { name: 'Ignite', value: 54 }, { name: 'Oxbar', value: 45 }]
  const categories = [{ name: 'Descartables', value: 158, color: 'purple' }, { name: 'Líquidos', value: 76, color: 'mint' }, { name: 'Resistencias', value: 42, color: 'orange' }, { name: 'Pods', value: 28, color: 'blue' }, { name: 'Accesorios', value: 18, color: 'gray' }]
  const methods = [{ name: 'Transferencia', value: 142 }, { name: 'Efectivo', value: 96 }, { name: 'Débito', value: 58 }, { name: 'Crédito', value: 26 }]
  const billing = [{ month: 'Ene', value: 210 }, { month: 'Feb', value: 265 }, { month: 'Mar', value: 320 }, { month: 'Abr', value: 290 }, { month: 'May', value: 380 }, { month: 'Jun', value: 345 }]
  const max = (items: { value: number }[]) => Math.max(...items.map(item => item.value))
  return <main className="app-shell"><Sidebar active="Reportes" onNavigate={onNavigate} /><section className="main-content"><header className="topbar"><div className="breadcrumbs"><span>Glauss Shop</span><span>/</span><strong>Reportes</strong></div><div className="top-actions"><button className="icon-button" aria-label="Buscar"><Search /></button><button className="icon-button" aria-label="Notificaciones">●</button></div></header><div className="content-wrap reports-page"><div className="page-heading"><div><p className="eyebrow">ANÁLISIS DEL NEGOCIO</p><h1>Reportes</h1><p className="heading-subtitle">Entendé qué se vende y cómo evoluciona tu tienda.</p></div><label className="filter-control report-range"><span>Período</span><select value={range} onChange={event => setRange(event.target.value)}><option>Últimos 6 meses</option><option>Este año</option><option>Últimos 30 días</option></select><ChevronDown /></label></div><div className="reports-grid"><ReportBars title="Productos más vendidos" subtitle="Top 8 por unidades" items={products} tone="purple" max={max(products)} /><ReportBars title="Marcas más vendidas" subtitle="Unidades vendidas" items={brands} tone="mint" max={max(brands)} /><DonutReport title="Ventas por categoría" items={categories} total="322 unidades" /><DonutReport title="Ventas por método de pago" items={methods.map((item, index) => ({ ...item, color: ['purple', 'mint', 'orange', 'blue'][index] }))} total="322 ventas" /><div className="card report-card report-line-card"><div className="report-card-head"><div><h2>Evolución de facturación</h2><p>Ingresos mensuales · en miles de pesos</p></div><span className="report-total">$ 1.810.000</span></div><div className="line-chart">{billing.map(item => <div className="line-column" key={item.month}><div className="line-point" style={{ bottom: `${item.value / 4}px` }}><span>{item.value}</span></div><div className="line-track"><i style={{ height: `${item.value / 4}px` }} /></div><small>{item.month}</small></div>)}</div></div></div></div></section></main>
}

function ReportBars({ title, subtitle, items, tone, max }: { title: string; subtitle: string; items: { name: string; value: number }[]; tone: string; max: number }) { return <div className="card report-card"><div className="report-card-head"><div><h2>{title}</h2><p>{subtitle}</p></div></div><div className="horizontal-bars">{items.map(item => <div className="horizontal-row" key={item.name}><span title={item.name}>{item.name}</span><div className="horizontal-track"><i className={tone} style={{ width: `${(item.value / max) * 100}%` }} /></div><strong>{item.value}</strong></div>)}</div></div> }

function DonutReport({ title, items, total }: { title: string; items: { name: string; value: number; color: string }[]; total: string }) { const totalValue = items.reduce((sum, item) => sum + item.value, 0); let cursor = 0; const gradient = items.map(item => { const start = (cursor / totalValue) * 100; cursor += item.value; return `var(--report-${item.color}) ${start}% ${(cursor / totalValue) * 100}%` }).join(', '); return <div className="card report-card donut-card"><div className="report-card-head"><div><h2>{title}</h2><p>Distribución del período</p></div></div><div className="donut-content"><div className="donut" style={{ background: `conic-gradient(${gradient})` }}><div><strong>{totalValue}</strong><span>{total}</span></div></div><div className="donut-legend">{items.map(item => <span key={item.name}><i className={item.color} />{item.name}<b>{Math.round((item.value / totalValue) * 100)}%</b></span>)}</div></div></div> }

function Reactivation({ clients, onNavigate }: { clients: Client[]; onNavigate: (view: 'clientes' | 'reactivacion' | 'productos' | 'finanzas' | 'reportes') => void }) {
  const [threshold, setThreshold] = useState(30)
  const reference = new Date('2024-06-20T12:00:00')
  const rows = clients.map((client, index) => {
    const [day, month, year] = client.lastPurchase.split('/').map(Number)
    const date = new Date(year, month - 1, day)
    const days = Math.max(31, Math.floor((reference.getTime() - date.getTime()) / 86400000) + index * 2)
    return { client, days, product: ['Pod menta + líquido 30ml', 'Líquido frutilla x2', 'Resistencia 0.8Ω + pod', 'Líquido sandía 60ml'][index % 4] }
  }).filter(row => row.days >= threshold).sort((a, b) => b.days - a.days)
  const potential = rows.reduce((sum, row) => sum + row.client.spent / Math.max(row.client.purchases, 1), 0)
  const whatsapp = (row: typeof rows[number]) => `https://wa.me/${row.client.phone.replace(/\\D/g, '')}?text=${encodeURIComponent(`Hola ${row.client.first}! Tenemos novedades en Glauss 🌬️`)}`
  return <main className="app-shell"><Sidebar active="Reactivación" onNavigate={onNavigate} /><section className="main-content"><header className="topbar"><div className="breadcrumbs"><span>Glauss Shop</span><span>/</span><strong>Reactivación</strong></div><div className="top-actions"><button className="icon-button" aria-label="Buscar"><Search /></button><button className="icon-button" aria-label="Notificaciones">●</button></div></header><div className="content-wrap reactivation-page"><div className="page-heading"><div><p className="eyebrow">RECUPERÁ CLIENTES</p><h1>Reactivación</h1><p className="heading-subtitle">Clientes que no compran hace más de 30 días</p></div></div><div className="metrics-grid reactivation-metrics"><Metric icon={<span className="metric-dot orange" />} label="Total a reactivar" value={rows.length.toString()} tone="peach" /><Metric icon={<span className="metric-dot purple" />} label="Facturación potencial recuperable" value={money(Math.round(potential))} tone="purple" /></div><div className="reactivation-toolbar"><div className="filter-pills" role="group" aria-label="Filtrar por antigüedad">{[30, 45, 60, 90].map(days => <button key={days} className={threshold === days ? 'filter-pill selected' : 'filter-pill'} onClick={() => setThreshold(days)}>{days}+</button>)}</div><span className="result-count">{rows.length} clientes</span></div><div className="card clients-table-card reactivation-table-card"><div className="clients-table-head"><div><h2>Clientes para contactar</h2><p>Ordenados por tiempo desde la última compra</p></div></div><div className="sales-table-wrap"><table className="clients-table reactivation-table"><thead><tr><th>Nombre y apellido</th><th>Teléfono</th><th>Última compra</th><th>Días sin comprar</th><th>Qué compró la última vez</th><th>Total histórico gastado</th><th></th></tr></thead><tbody>{rows.map(row => <tr key={row.client.id}><td><strong>{row.client.first} {row.client.last}</strong></td><td>{row.client.phone}</td><td>{row.client.lastPurchase}</td><td><span className={`days-pill ${row.days >= 90 ? 'danger' : 'warning'}`}>{row.days} días</span></td><td>{row.product}</td><td><strong>{money(row.client.spent)}</strong></td><td><a className="contact-whatsapp" href={whatsapp(row)} target="_blank" rel="noreferrer"><Phone /> Contactar por WhatsApp</a></td></tr>)}</tbody></table></div></div></div></section></main>
}

function SaleDetail({ sale, onBack }: { sale: Sale; onBack: () => void }) {
  const items = sale.products.includes('+')
    ? [{ name: sale.products.split(' + ')[0], brand: 'Elfbar', quantity: 1, price: Math.round(sale.total * 0.58) }, { name: 'Líquido Menta 60ml', brand: 'Ignite', quantity: 1, price: Math.round(sale.total * 0.42) }]
    : [{ name: sale.products, brand: sale.products.includes('Líquido') ? 'Ignite' : sale.products.includes('XROS') ? 'Vaporesso' : 'Elfbar', quantity: 1, price: sale.total }]
  return <main className="app-shell"><Sidebar active="Ventas" /><section className="main-content"><header className="topbar"><div className="breadcrumbs"><span>Glauss Shop</span><span>/</span><strong>Detalle de venta</strong></div></header><div className="content-wrap sale-detail-page"><button className="back-link" onClick={onBack}><ArrowLeft /> Volver</button><div className="detail-heading"><div><p className="eyebrow">DETALLE DE OPERACIÓN</p><h1>Venta N° {String(sale.id).padStart(4, '0')}</h1><p className="heading-subtitle">Registrada el {sale.date}</p></div></div><div className="sale-customer-card card"><div className="big-avatar">{sale.client.split(' ').map(part => part[0]).join('')}</div><div className="sale-customer-info"><span>CLIENTE</span><strong>{sale.client}</strong><small>Cliente habitual de Glauss</small></div><div className="sale-customer-contact"><span>{initialClients.find(client => `${client.first} ${client.last}` === sale.client)?.phone ?? '+54 9 221 555-0182'}</span><button className="whatsapp-button" onClick={() => window.open(`https://wa.me/${(initialClients.find(client => `${client.first} ${client.last}` === sale.client)?.phone ?? '').replace(/\D/g, '')}`, '_blank')}><Phone /> WhatsApp</button></div></div><div className="card sale-items-card"><div className="section-title"><div><h2>Ítems de la venta</h2><p>{items.length} productos registrados</p></div></div><div className="sales-table-wrap"><table className="clients-table purchase-table"><thead><tr><th>Producto</th><th>Marca</th><th>Cantidad</th><th>Precio unitario</th><th>Subtotal</th></tr></thead><tbody>{items.map(item => <tr key={item.name}><td><strong className="strong-cell">{item.name}</strong></td><td>{item.brand}</td><td>{item.quantity}</td><td>{money(item.price)}</td><td><strong className="strong-cell">{money(item.price * item.quantity)}</strong></td></tr>)}</tbody></table></div><div className="sale-detail-summary"><div><span>Método de pago</span><b className={`payment-pill ${sale.method.toLowerCase()}`}>{sale.method}</b></div><div className="sale-detail-total"><span>Total</span><strong>{money(sale.total)}</strong></div></div></div></div></section></main>
}

function ClientDetail({ client, onBack }: { client: Client; onBack: () => void }) { const monthly = [{ month: 'Ene', value: 34 }, { month: 'Feb', value: 52 }, { month: 'Mar', value: 41 }, { month: 'Abr', value: 68 }, { month: 'May', value: 92 }]; const purchases = [{ date: '14/05/2024', products: 'Pod menta, Líquido 30ml', method: 'Transferencia', total: 48200 }, { date: '28/04/2024', products: 'Líquido frutilla x2', method: 'Efectivo', total: 36700 }, { date: '09/03/2024', products: 'Resistencia 0.8Ω, Pod', method: 'Débito', total: 52900 }]; return <main className="app-shell"><Sidebar active="Clientes" /><section className="main-content"><header className="topbar"><div className="breadcrumbs"><span>Glauss Shop</span><span>/</span><strong>Ficha de cliente</strong></div></header><div className="content-wrap client-detail-page"><button className="back-link" onClick={onBack}><ArrowLeft /> Volver a clientes</button><div className="detail-heading"><div><p className="eyebrow">FICHA DE CLIENTE</p><h1>{client.first} {client.last}</h1><p className="heading-subtitle">Cliente desde enero de 2024</p></div><button className="whatsapp-button" onClick={() => window.open(`https://wa.me/${client.phone.replace(/\D/g, '')}`, '_blank')}><Phone /> WhatsApp</button></div><div className="detail-columns"><div className="detail-left"><div className="card profile-card"><div className="profile-top"><div className="big-avatar">{initials(client)}</div><div className="profile-name"><h2>{client.first} {client.last}</h2><span className={`status-pill ${client.status === 'Activo' ? 'active' : 'reactivate'}`}>{client.status}</span></div></div><div className="contact-list"><p><Phone /> {client.phone}</p><p>✉ {client.first.toLowerCase()}.{client.last.toLowerCase()}@gmail.com</p></div><div className="profile-actions"><button className="whatsapp-button"><Phone /> WhatsApp</button><button className="outline-button">Editar</button></div></div><div className="metrics-grid detail-metrics"><Metric icon={<span className="metric-dot green" />} label="Total gastado" value={money(client.spent)} tone="mint" /><Metric icon={<ShoppingBag />} label="Cantidad de compras" value={client.purchases.toString()} tone="purple" /><Metric icon={<span className="metric-dot orange" />} label="Última compra" value={client.lastPurchase} tone="peach" /></div><div className="card notes-card"><div className="section-title"><div><h2>Notas</h2><p>Información útil sobre este cliente</p></div><button className="text-button">Editar</button></div><p className="notes-copy">Prefiere pods de menta y suele comprar para la novia.</p></div></div><div className="card purchase-history"><div className="section-title"><div><h2>Historial de compras</h2><p>Últimas compras realizadas</p></div><button className="date-button">Ver todas <ChevronRight /></button></div><div className="spend-chart"><div className="chart-heading"><span>Gasto por mes</span><strong>{money(client.spent)}</strong></div><div className="bars">{monthly.map(item => <div className="bar-column" key={item.month}><span className="bar-value">{item.value}k</span><div className="bar" style={{ height: `${item.value}%` }} /><small>{item.month}</small></div>)}</div></div><div className="purchase-table-wrap"><table className="purchase-table"><thead><tr><th>Fecha</th><th>Productos</th><th>Método</th><th>Total</th></tr></thead><tbody>{purchases.map(purchase => <tr key={purchase.date}><td>{purchase.date}</td><td>{purchase.products}</td><td>{purchase.method}</td><td><strong>{money(purchase.total)}</strong></td></tr>)}</tbody></table></div></div></div></div></section></main> }

function NewProduct({ onClose }: { onClose: () => void }) { const [name, setName] = useState(''); const [brand, setBrand] = useState(''); const [category, setCategory] = useState('Descartables'); const [price, setPrice] = useState(''); const [stock, setStock] = useState(''); const [minimum, setMinimum] = useState(''); const [description, setDescription] = useState(''); const categories = ['Descartables', 'Pods', 'Líquidos', 'Resistencias', 'Baterías y Mods', 'Accesorios']; const canSave = name && brand && price && stock && minimum; return <div className="modal-backdrop"><section className="sale-modal new-client-modal new-product-modal" role="dialog" aria-modal="true" aria-labelledby="new-product-title"><header><div><p className="eyebrow">CATÁLOGO E INVENTARIO</p><h2 id="new-product-title">Nuevo producto</h2></div><button className="close-button" onClick={onClose} aria-label="Cerrar"><X /></button></header><div className="modal-body"><label className="field"><span>Nombre del producto</span><input value={name} onChange={event => setName(event.target.value)} placeholder="Ej. BC5000 Blue Razz" /></label><div className="modal-fields"><label className="field"><span>Marca</span><input value={brand} onChange={event => setBrand(event.target.value)} placeholder="Ej. Elfbar" /></label><label className="field"><span>Categoría</span><select value={category} onChange={event => setCategory(event.target.value)}>{categories.map(item => <option key={item}>{item}</option>)}</select></label></div><div className="modal-fields"><label className="field"><span>Precio ($)</span><input type="number" min="0" value={price} onChange={event => setPrice(event.target.value)} placeholder="Ej. 18500" /></label><label className="field"><span>Stock actual</span><input type="number" min="0" value={stock} onChange={event => setStock(event.target.value)} placeholder="Ej. 24" /></label></div><label className="field"><span>Stock mínimo <em>(para alertas)</em></span><input type="number" min="0" value={minimum} onChange={event => setMinimum(event.target.value)} placeholder="Ej. 10" /></label><label className="field"><span>Descripción <em>(opcional)</em></span><textarea value={description} onChange={event => setDescription(event.target.value)} placeholder="Agregá una descripción del producto" rows={3} /></label></div><footer><button className="cancel-button" onClick={onClose}>Cancelar</button><button className="quick-button" disabled={!canSave}>Guardar producto</button></footer></section></div> }

function NewClient({ onClose, onCreate }: { onClose: () => void; onCreate: (client: Omit<Client, 'id'>) => void }) { const [first, setFirst] = useState(''); const [last, setLast] = useState(''); const [phone, setPhone] = useState(''); const [email, setEmail] = useState(''); const [notes, setNotes] = useState(''); return <div className="modal-backdrop"><section className="sale-modal new-client-modal" role="dialog" aria-modal="true" aria-labelledby="new-client-title"><header><div><p className="eyebrow">NUEVO REGISTRO</p><h2 id="new-client-title">Nuevo cliente</h2></div><button className="close-button" onClick={onClose} aria-label="Cerrar"><X /></button></header><div className="modal-body"><div className="modal-fields"><label className="field"><span>Nombre</span><input value={first} onChange={event => setFirst(event.target.value)} placeholder="Ej. Martina" /></label><label className="field"><span>Apellido</span><input value={last} onChange={event => setLast(event.target.value)} placeholder="Ej. González" /></label></div><label className="field"><span>Teléfono</span><input value={phone} onChange={event => setPhone(event.target.value)} placeholder="+54 9 221..." /></label><label className="field"><span>Email <em>(opcional)</em></span><input type="email" value={email} onChange={event => setEmail(event.target.value)} placeholder="Ej. martina@email.com" /></label><label className="field"><span>Notas <em>(opcional)</em></span><textarea value={notes} onChange={event => setNotes(event.target.value)} placeholder="Ej. prefiere pods de menta, compra para la novia" rows={3} /></label></div><footer><button className="cancel-button" onClick={onClose}>Cancelar</button><button className="quick-button" disabled={!first || !last || !phone} onClick={() => onCreate({ first, last, phone, lastPurchase: 'Sin compras', purchases: 0, spent: 0, status: 'Activo' })}>Guardar cliente</button></footer></section></div> }

